/// A task in a list or detail.
class TaskItem {
  /// Block ID (`t-…`).
  final String id;

  /// The note holding the line.
  final String noteId;

  /// That note's title.
  final String noteTitle;

  /// Description (no emoji fields).
  final String description;

  /// State.
  final TaskState state;

  /// Priority (`highest` … `lowest`, `normal`).
  final String priority;

  /// 📅 due.
  final DateTime? due;

  /// ⏳ scheduled.
  final DateTime? scheduled;

  /// ✅ done date.
  final DateTime? done;

  /// Recurrence phrase as written (`every month on the 1st`).
  final String? recurrence;

  /// `false` when the phrase is outside the grammar ("recurrence not understood").
  final bool recurrenceUnderstood;

  /// Reminders.
  final List<ReminderItem> reminders;

  /// Linked notes/entities (wikilinks in the line).
  final List<EntityRef> links;

  /// Has unsynced changes.
  final bool pendingSync;

  /// Direction of `description`.
  final TextDir descriptionDir;

  /// Path of the note holding the line ("tasks/Tasks.md").
  final String notePath;

  /// 1-based line number of the task in that file.
  final int lineNumber;

  /// Due date as a label ("Today", "Tomorrow", "Tue 29 Sep", "1 Oct 2027").
  final String? dueLabel;

  /// Open and due before today: "3 days late".
  final String? latenessLabel;

  /// Done/cancelled: "on time" / "2 days late" (history rows).
  final String? completionLabel;

  /// Open and recurring: "next in 4 days" (time to the due/scheduled date).
  final String? nextInLabel;

  /// Where it came from ("From document expiry" for tasks linking a document with an
  /// expiry date), when known.
  final String? originLabel;

  /// Open and due before today.
  final bool isOverdue;

  const TaskItem({
    required this.id,
    required this.noteId,
    required this.noteTitle,
    required this.description,
    required this.state,
    required this.priority,
    this.due,
    this.scheduled,
    this.done,
    this.recurrence,
    required this.recurrenceUnderstood,
    required this.reminders,
    required this.links,
    required this.pendingSync,
    required this.descriptionDir,
    required this.notePath,
    required this.lineNumber,
    this.dueLabel,
    this.latenessLabel,
    this.completionLabel,
    this.nextInLabel,
    this.originLabel,
    required this.isOverdue,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      noteId.hashCode ^
      noteTitle.hashCode ^
      description.hashCode ^
      state.hashCode ^
      priority.hashCode ^
      due.hashCode ^
      scheduled.hashCode ^
      done.hashCode ^
      recurrence.hashCode ^
      recurrenceUnderstood.hashCode ^
      reminders.hashCode ^
      links.hashCode ^
      pendingSync.hashCode ^
      descriptionDir.hashCode ^
      notePath.hashCode ^
      lineNumber.hashCode ^
      dueLabel.hashCode ^
      latenessLabel.hashCode ^
      completionLabel.hashCode ^
      nextInLabel.hashCode ^
      originLabel.hashCode ^
      isOverdue.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TaskItem &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          noteId == other.noteId &&
          noteTitle == other.noteTitle &&
          description == other.description &&
          state == other.state &&
          priority == other.priority &&
          due == other.due &&
          scheduled == other.scheduled &&
          done == other.done &&
          recurrence == other.recurrence &&
          recurrenceUnderstood == other.recurrenceUnderstood &&
          reminders == other.reminders &&
